buy6.reactions=[{trigger:{type:'ON_CLICK'}, actions:[{type:'NODE', destinationId: f7.id, navigation:'OVERLAY', transition:{type:'DISSOLVE', easing:{type:'EASE_OUT'}, duration:0.2}, overlayRelativePosition:null, resetVideoPosition:false, resetScrollPosition:true, resetInteractiveComponents:false}]}];
